// Grammar labels and lessons: SKELETON, in memory only.
// Nothing here is stored or synced yet, so nothing has to stay compatible. The real store is plan WP2
// (.claude/plans/2026-11-20-grammar-window.md §4): kv rows `gl:<note id>` / `gx:<note id>`, synced as
// `grammar/<dev>/<YYYY-MM>.json.gz` with its own dirty queue, like explain (EXP-2). Lessons are generated by WP3.
import { useSyncExternalStore } from 'react';
import type { Note } from '../types';
import type { GrammarLabel, LessonEntry, TitleLang } from './types';

interface GrammarState {
  labels: ReadonlyMap<string, GrammarLabel>;
  lessons: ReadonlyMap<string, LessonEntry>;
}

let state: GrammarState = { labels: new Map(), lessons: new Map() };
const listeners = new Set<() => void>();

function set(next: Partial<GrammarState>): void {
  state = { ...state, ...next };
  for (const l of listeners) l();
}

function subscribe(l: () => void): () => void {
  listeners.add(l);
  return () => listeners.delete(l);
}

export function getGrammarState(): GrammarState {
  return state;
}

export function useGrammar(): GrammarState {
  return useSyncExternalStore(subscribe, getGrammarState);
}

/** Hugo edits a label. A field set to undefined clears it. Hugo's labels are never replaced by Claude's suggestions. */
export function setLabel(noteId: string, patch: Pick<GrammarLabel, 'hsk' | 'family'>): void {
  const prev = state.labels.get(noteId);
  const next: GrammarLabel = { ...prev, ...patch, src: 'hugo', at: Date.now() };
  const labels = new Map(state.labels);
  labels.set(noteId, next);
  set({ labels });
}

/** Claude's suggestions for many points: applied only where Hugo has set nothing. */
export function applySuggestedLabels(suggested: Map<string, Pick<GrammarLabel, 'hsk' | 'family'>>, now = Date.now()): void {
  const labels = new Map(state.labels);
  for (const [id, s] of suggested) {
    if (labels.get(id)?.src === 'hugo') continue;
    labels.set(id, { ...s, src: 'claude', at: now });
  }
  set({ labels });
}

export class NotReadyError extends Error {
  constructor(what: string) {
    super(`${what} is not built yet`);
    this.name = 'NotReadyError';
  }
}

/** True once lesson generation (WP3) exists. The UI hides the generate buttons while false. */
export const LESSONS_READY = false;

/** WP3: ask Claude for the lesson of one point (French + English in one call), save it, return it. */
export async function requestLesson(_note: Note): Promise<LessonEntry> {
  throw new NotReadyError('Lesson generation');
}

/** WP3: one Claude call that suggests HSK level and family for every unlabelled point. */
export async function suggestAllLabels(_notes: Note[]): Promise<number> {
  throw new NotReadyError('Label suggestions');
}

// ---------- device-only UI state (not a pref, never synced; like QUICK-1) ----------

const LANG_KEY = 'hz.gr.lang';

export function readTitleLang(): TitleLang {
  try {
    const v = localStorage.getItem(LANG_KEY);
    return v === 'fr' || v === 'en' ? v : 'zh';
  } catch {
    return 'zh';
  }
}

export function saveTitleLang(l: TitleLang): void {
  try {
    localStorage.setItem(LANG_KEY, l);
  } catch {
    /* private mode: the switch still works for this visit */
  }
}

/** Tests only. */
export function _resetGrammar(): void {
  set({ labels: new Map(), lessons: new Map() });
}

/** Tests and WP2 only: put lessons in memory. */
export function _putLessons(entries: LessonEntry[]): void {
  const lessons = new Map(state.lessons);
  for (const e of entries) {
    const prev = lessons.get(e.k);
    if (!prev || prev.at < e.at) lessons.set(e.k, e);
  }
  set({ lessons });
}
